import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useLocation } from 'react-router-dom';
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';
import HomePage from './components/HomePage/HomePage';
import LoginPage from './components/LoginPage/LoginPage';
import SignupPage from './components/SignupPage/SignupPage';
import ProfilePage from './components/ProfilePage/ProfilePage';
import JoinGamePage from './components/JoinGamePage/JoinGamePage';
import NewGamePage from './components/NewGamePage/NewGamePage';
import NotFoundPage from './components/NotFoundPage/NotFoundPage';
import PrivateRoute from './components/PrivateRoute/PrivateRoute';
import { AuthProvider, useAuth } from './context/AuthContext';
import { SocketProvider } from './context/SocketContext';
import './App.css';

function App() {
  const AuthRedirect = ({ children }) => {
    const { isAuthenticated, axiosAuth } = useAuth();
    const location = useLocation();
  
    useEffect(() => {
      const params = new URLSearchParams(location.search);
      const referrer = params.get('referrer');
  
      if (referrer && isAuthenticated) {
        axiosAuth.post("/users/set-app-token", { appToken: referrer });
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [location.search]);
  
    return isAuthenticated ? <Navigate to="/" /> : children;
  };

  return (
    <AuthProvider>
      <SocketProvider>
        <Router>
          <div className="App">
            <Header />
            <Routes>
              <Route path="/" element={<HomePage />} />
              <Route path="/login" element={<AuthRedirect><LoginPage /></AuthRedirect>} />
              <Route path="/signup" element={<AuthRedirect><SignupPage /></AuthRedirect>} />
              <Route element={<PrivateRoute />}>
                <Route path="/profile/:userId" element={<ProfilePage />} />
                <Route path="/join-game" element={<JoinGamePage />} />
                <Route path="/new-game" element={<NewGamePage />} />
              </Route>
              <Route path="*" element={<NotFoundPage />} />
            </Routes>
            <Footer />
          </div>
        </Router>
      </SocketProvider>
    </AuthProvider>
  );
}

export default App;
